-- The column contrib_med_registry links to demographics.contrib_registry (donors)
-- But the risk_evaluation links both donor and recipient through transplant_matching

-- Let me check if the counts make sense by looking at total records
SELECT COUNT(*) FROM medical_history;
SELECT COUNT(*) FROM transplant_matching;
SELECT COUNT(*) FROM risk_evaluation;

