-- Let me check what columns exist in risk_evaluation

SELECT column_name FROM information_schema.columns WHERE table_name = 'risk_evaluation' ORDER BY ordinal_position;

-- The risk_evaluation table has surg_risk_val which might be the actual "risk score"
-- Let me check if this is the right column to use

SELECT DISTINCT surg_risk_val FROM risk_evaluation LIMIT 10;

